      color: var(--muted);
      font-size: 0.95rem;
    }

    .delete-btn,
    .confirm-btn,
    .cancel-btn {
      border: 0;
      border-radius: 999px;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
    }

    .delete-btn {
      background: var(--danger-soft);
      color: var(--danger);
      padding: 12px 18px;
    }

    .delete-btn:hover,
    .confirm-btn:hover,
    .cancel-btn:hover {
      transform: translateY(-1px);
    }

    .delete-btn:focus-visible,
    .confirm-btn:focus-visible,
    .cancel-btn:focus-visible,
    .close-btn:focus-visible {
      outline: none;
      box-shadow: var(--ring);
    }

    dialog {
      width: min(92vw, 480px);
      border: 1px solid rgba(19, 34, 56, 0.12);
      border-radius: 28px;
      padding: 0;
      box-shadow: var(--shadow);
      background: #fff;
      color: var(--text);
    }

    dialog::backdrop {
      background: rgba(10, 15, 28, 0.45);
      backdrop-filter: blur(4px);
    }

    .dialog-body {
      padding: 24px;
    }

    .dialog-top {
      display: flex;
      justify-content: space-between;
      align-items: start;
      gap: 12px;
      margin-bottom: 16px;
    }

    .dialog-icon {
      width: 48px;
      height: 48px;
      border-radius: 16px;
      display: grid;
      place-items: center;
      background: linear-gradient(180deg, #fee2e2, #fecaca);
      color: var(--danger);
      flex: 0 0 auto;
      font-size: 1.25rem;
      font-weight: 900;
    }

    .close-btn {
