      border-radius: 999px;
      cursor: pointer;
      font-size: 1.2rem;
      line-height: 1;
    }

    .dialog-title {
      margin: 0 0 8px;
      font-size: 1.35rem;
    }

    .dialog-text {
      margin: 0;
      color: var(--muted);
      line-height: 1.55;
    }

    .dialog-actions {
      display: flex;
      gap: 12px;
      justify-content: flex-end;
      padding: 0 24px 24px;
      flex-wrap: wrap;
    }

    .cancel-btn {
      background: #e2e8f0;
      color: #0f172a;
      padding: 12px 18px;
    }

    .confirm-btn {
      background: var(--danger);
      color: white;
      padding: 12px 18px;
      box-shadow: 0 14px 28px rgba(220, 38, 38, 0.22);
    }

    .confirm-btn:active,
    .delete-btn:active,
    .cancel-btn:active {
      transform: translateY(0);
    }

    @media (max-width: 560px) {
      .page {
        padding: 20px;
        border-radius: 24px;
      }

      .image-meta {
        padding: 16px;
      }

      .dialog-actions {
        padding: 0 20px 20px;
      }
    }
  </style>
</head>
<body>
  <main class="page">
    <div class="header">
      <div>
        <p class="eyebrow">Image preview</p>
        <h1>Sunset over the water</h1>
        <p class="subtitle">Review this photo before you decide whether to keep it in your library.</p>
      </div>
    </div>

    <section class="image-card" aria-label="Preview of selected image">
      <img
        class="preview"
        src="https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=1400&q=80"
        alt="A warm sunset reflecting on a calm lake"
      />
      <div class="image-meta">
        <div class="meta-copy">
          <strong>Lake View 024</strong>
          <span>Added to your library yesterday</span>
        </div>
        <button class="delete-btn trigger" type="button" aria-controls="delete-dialog">
          Delete image
        </button>
      </div>
    </section>
  </main>

  <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-desc">
    <div class="dialog-body">
      <div class="dialog-top">
        <div class="dialog-icon" aria-hidden="true">!</div>
        <button class="close-btn" type="button" aria-label="Close dialog">×</button>
      </div>
      <h2 class="dialog-title" id="delete-title">Delete this image?</h2>
      <p class="dialog-text" id="delete-desc">
        This will remove the image from your library. You can&apos;t undo this action.
      </p>
    </div>
    <div class="dialog-actions">
      <button class="cancel-btn" type="button">Cancel</button>
      <button class="confirm-btn" type="button">Yes, delete</button>
    </div>
  </dialog>

  <script>
    const dialog = document.getElementById('delete-dialog');
    const trigger = document.querySelector('.trigger');
    const closeButtons = dialog.querySelectorAll('.cancel-btn, .close-btn');
    const confirmButton = dialog.querySelector('.confirm-btn');

    trigger.addEventListener('click', () => {
      dialog.showModal();
    });

    closeButtons.forEach((button) => {
      button.addEventListener('click', () => {
        dialog.close();
      });
    });

    confirmButton.addEventListener('click', () => {
      dialog.close();
    });

    dialog.addEventListener('click', (event) => {
      const rect = dialog.getBoundingClientRect();
      const isBackdropClick =
        event.clientX < rect.left ||
        event.clientX > rect.right ||
        event.clientY < rect.top ||
        event.clientY > rect.bottom;

      if (isBackdropClick) {
        dialog.close();
      }
    });
  </script>
</body>
</html>
